using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct KnowledgeId : IEquatable<KnowledgeId>, IComparable<KnowledgeId>
    {
        public Guid Value { get; }

        public KnowledgeId(Guid value)
        {
            Value = value;
        }

        public static KnowledgeId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static KnowledgeId NewRandom() => new KnowledgeId(Guid.NewGuid());

        public static KnowledgeId Parse(string text) => new KnowledgeId(Guid.Parse(text));

        public static bool TryParse(string text, out KnowledgeId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new KnowledgeId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(KnowledgeId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is KnowledgeId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(KnowledgeId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(KnowledgeId left, KnowledgeId right) => left.Equals(right);

        public static bool operator !=(KnowledgeId left, KnowledgeId right) => !left.Equals(right);
    }
}
